INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134977, 'spa', 'Causar que alguien o algo este saturado, satisfacer o refrescar', 'Causar que alguien o algo este saturado, satisfacer o refrescar. Sentido causativo del Hifil. Dios sacia al alma fatigada (Jer 31:25) y la persona generosa es ella misma refrescada (Pr 11:25). Isaias 55:10 extiende este sentido a la lluvia que riega la tierra y la hace producir, subrayando la eficacia completa de la accion causativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134979, 'spa', 'Satisfacer profundamente, embriagar o causar una saciedad intensa', 'Satisfacer profundamente, embriagar o causar una saciedad intensa. Piel intensivo con objetos personales o abstractos. En Proverbios 5:19 el esposo debe estar siempre embriagado del amor de su esposa; en Isaias 34:5 la espada del SENOR esta ebria de sangre. El tronco intensivo va mas alla del simple llenar hasta el exceso o la desmesura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134988, 'spa', 'Regado, floreciente', 'El término caracteriza vegetación bien irrigada y floreciente como metáfora de bendición y prosperidad. Isaías 58:11 y Jeremías 31:12 ambos prometen restauración usando la imagen de ''un jardín regado'', uno que nunca falla por falta de agua, constantemente refrescado y productivo. Deuteronomio 29:19 lo emplea en una advertencia más oscura: la persona impenitente piensa que la seguridad viene de la terquedad, así ''destruyendo lo regado con lo sediento'' en juicio colectivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134990, 'spa', 'Amplitud y alivio', 'La raíz captura tanto la espaciosidad física como el alivio que el espacio trae. Primera de Samuel 16:23 describe cómo la música alivió el tormento de Saúl: ''y hubo alivio para él'', sugiriendo que el agarre del espíritu opresivo se aflojó, creando espacio psicológico. Job 32:20 lo usa para el alivio que viene al hablar: ''para que tenga alivio''—las palabras liberando presión interna. Jeremías 22:14 lo emplea literalmente para cuartos espaciosos y bien acondicionados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (134992, 'spa', 'Oler (literal)', 'El acto literal de oler — percibir un aroma a través de la nariz. Abarca toda la gama de experiencia olfativa: Dios oliendo la ofrenda quemada de Noé (Gn 8:21), Isaac oliendo las vestiduras de su hijo (Gn 27:27), la prohibición de fabricar incienso para uso personal (Éx 30:38), Dios negándose a oler las ofrendas del Israel infiel (Lv 26:31) y los ídolos que ''tienen nariz pero no huelen'' (Sal 115:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135000, 'spa', 'Deleitarse en (metafórico)', 'Una extensión metafórica donde ''oler'' se convierte en ''deleitarse en'' o ''saborear'' — experimentar placer con la inmediatez profunda e instintiva que evoca el olfato. Se emplea en Is 11:3 respecto al deleite del Mesías en el temor del SEÑOR (וַהֲרִיחוֹ בְּיִרְאַת יְהוָה). Las traducciones ''su deleite'' en español y ''his delight'' en inglés abandonan todo vocabulario olfativo, confirmando el giro plenamente metafórico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135001, 'spa', 'Espíritu de Dios', 'El Espíritu de Dios, el Espíritu Santo: agente divino de la creación, la profecía, el empoderamiento y la revelación (96 casos). Aparece característicamente en estado constructo con nombres divinos: רוּחַ אֱלֹהִים (Gn 1:2), רוּחַ יהוה (Jue 3:10). Las lenguas de destino marcan el referente divino con mayúscula u otros recursos: Espíritu de Dios, Geist Gottes, 하나님의 영.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135002, 'spa', 'viento meteorológico', 'Viento físico, movimiento natural del aire (113 casos): incluye el viento del este que seca mares y destruye cosechas, tempestades, brisas suaves y los cuatro vientos como fuerzas cósmicas. Pasajes clave: Gn 8:1, donde Dios envía un viento sobre las aguas, y Job 1:19, donde un gran viento derriba la casa. Árabe رِيح, coreano 바람 y hindi हवा convergen aquí.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135003, 'spa', 'espíritu / ánimo humano', 'El espíritu humano, la disposición interior, el ánimo, el estado de ánimo o la vida inmaterial: sede de las emociones, la voluntad y el valor (145 casos). Incluye la ''cortedad de espíritu'' (Éx 6:9, impaciencia/angustia), un ''espíritu nuevo'' (Ez 18:31) y un ''espíritu generoso'' (Sal 51:12). Cada lengua escoge de su propio repertorio interior: coreano 심령/마음, suajili roho, hindi मन/आत्मा.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135011, 'spa', 'aliento / soplo vital', 'El aliento físico, el soplo de vida, la fuerza vital que anima a los seres vivientes (15 casos). Gn 6:17 y 7:15 hablan del ''aliento de vida'' (רוּחַ חַיִּים) en toda carne. Al morir, el רוּחַ vuelve a Dios que lo dio (Ecl 12:7). Árabe نَفَس y hindi साँस/प्राण distinguen este sentido del viento o del espíritu propiamente dicho.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135014, 'spa', 'dirección / costado', 'Punto cardinal, dirección o costado, derivado metafóricamente de los cuatro vientos como marcadores espaciales (6 casos). Ez 42:16-20 emplea רוּחַ para cada uno de los cuatro lados del complejo del templo. Coreano 방향, hindi दिशा y suajili upande traducen con vocabulario direccional específico, confirmando un sentido espacial distinto del meteorológico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135022, 'spa', 'seres espirituales', 'Seres espirituales: entidades sobrenaturales como ángeles, demonios o espíritus inmundos (3 casos). Nm 16:22 y 27:16 invocan a Dios como ''Dios de los espíritus (רוּחֹת) de toda carne'', y Pr 16:2 habla de que Dios pesa los espíritus. Árabe أَرْوَاح (plural) y coreano 영들 marcan la lectura de entidades plurales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135085, 'spa', 'Espíritu (divino o humano)', 'Espíritu — ya sea divino o humano — como principio animador y cognoscitivo dentro de una persona. En el contexto cortesano de Daniel, los reyes babilonios y persas reconocen que Daniel posee ''el espíritu de los dioses santos'' (רוּחַ אֱלָהִין קַדִּישִׁין, Dn 4:8-9, 5:11), un espíritu extraordinario (רוּחַ יַתִּירָא, Dn 5:12, 6:4) que le otorga sabiduría excepcional. En Dn 5:20 el espíritu del rey se endurece, y en Dn 7:15 el espíritu de Daniel se turba por sus visiones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135088, 'spa', 'Viento (meteorológico)', 'Viento como fuerza meteorológica natural, presente únicamente en las dos grandes visiones de Daniel. En Dn 2:35, después de que la piedra golpea la estatua, el viento (רוּחָא) arrastra los fragmentos como tamo sin dejar rastro — una imagen vívida de obliteración total. En Dn 7:2, los cuatro vientos del cielo (רוּחֵי שְׁמַיָּא) agitan el gran mar del cual emergen las cuatro bestias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135093, 'spa', 'levantar, alzar (físico)', 'Sentido causativo Hifil de levantar, alzar o recoger físicamente un objeto, una parte del cuerpo o una persona. Abraham alza la mano para jurar (Gn 14:22), Jacob erige una estela (Gn 31:45), el copero levanta la cabeza de Faraón (Gn 40:20). Este sentido literal fundamenta todas las extensiones metafóricas de la raíz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135094, 'spa', 'contribuir, presentar (ofrenda)', 'Sentido especializado Hifil que denota el acto ritual de elevar una ofrenda (terumá) o hacer una contribución voluntaria al santuario. Los israelitas ''contribuyeron'' oro y plata para el tabernáculo (Éx 35:24); los levitas recibieron un tributo del botín (Nm 31:28, 52). Un término técnico cúltico distinto de levantar físicamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135095, 'spa', 'ser exaltado, elevarse', 'Sentido intransitivo Qal de elevarse, encumbrarse o ser exaltado sin agente externo. Las aguas del diluvio subieron (Gn 7:17), el rey de Israel se alzará con poder (Nm 24:7), los corazones se ensoberbecen (Dt 8:14; 17:20). Las traducciones captan la cualidad estativa o incoativa: árabe yartafi''u, coreano 높아지다.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135097, 'spa', 'alto, elevado (estativo)', 'Sentido estativo o participial Qal que describe una altura inherente u observable: personas de alta estatura (Dt 1:28; 2:10, 21), la ''mano alzada'' que simboliza audacia desafiante (Éx 14:8; Nm 33:3), montañas elevadas. La evidencia muestra una cualidad atributiva, no una acción, marcando el aspecto estativo de la raíz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135101, 'spa', 'quitar, remover', 'Sentido Hifil de levantar algo para apartarlo o eliminarlo: quitar un turbante (Ez 21:26), remover tropiezos (Is 57:14; 62:10), llevarse la deshonra (Pr 3:35). Las traducciones revelan el matiz direccional de remoción (árabe azāla, coreano 제거하다) que extiende la semántica básica de levantar en sentido sustractivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135102, 'spa', 'exaltar, honrar (estatus)', 'Sentido figurado Hifil de exaltar a alguien en rango, honor o poder: Dios exaltando a David al trono (1 S 2:10), sacerdotes elevados en estatus ritual (Lv 2:9; 6:10), el cuerno de Israel alzado en victoria (1 S 2:1). Las glosas multilingües distinguen esta elevación metafórica del acto físico de levantar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135106, 'spa', 'exaltado (majestad divina)', 'Sentido participial o estativo Qal aplicado exclusivamente a Dios como el Exaltado, expresando trascendencia y majestad divina: ''Estad quietos, y conoced que yo soy Dios; seré exaltado entre las naciones'' (Sal 46:10). Árabe muta''ālin y coreano 높으시도다 distinguen esta acepción de la exaltación humana del sentido 2.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135109, 'spa', 'ensalzar, exaltar (Piel)', 'Sentido intensivo Piel de alabar activamente, ensalzar o magnificar el nombre y la grandeza de Dios o de una persona. Moisés canta: ''Él es mi Dios y lo ensalzaré'' (Éx 15:2). Árabe ''aẓẓama, coreano 높이다 (intensivo) y suajili -tukuza reflejan el registro devocional intensificado que distingue esta acepción del mero levantar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135122, 'spa', 'exaltarse a sí mismo', 'Sentido reflexivo Hitpael donde el sujeto se exalta o enaltece a sí mismo: ''Seré exaltado entre las naciones'' (Is 33:10, dicho por Dios), o el rey impío que ''se enaltecerá y se engrandecerá sobre todo dios'' (Dn 11:36). La forma marca la dirección reflexiva de la exaltación, sea legítima (Dios) o blasfema (gobernantes humanos).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135157, 'spa', 'altivo, soberbio', 'Sentido moral negativo del participio Qal que describe al orgulloso, altivo o arrogante cuyos ojos o corazón se alzan en vanagloria. Proverbios condena los ''ojos altivos'' (6:17), Isaías advierte contra el ''día de Jehová sobre todo soberbio y enaltecido'' (2:12). Un descriptor de carácter, extensión moral de la raíz ''ser alto''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135184, 'spa', 'ser alzado (pasivo)', 'Sentido pasivo Hofal o Pual donde alguien o algo es alzado o exaltado por un agente externo. Los levitas llaman a Israel a ''exaltar al Señor'' esperando que su nombre ''sea exaltado'' (Neh 9:5), y el cuerno del justo ''será levantado'' por Dios (Sal 75:10). Las glosas reflejan la recepción pasiva de la exaltación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135235, 'spa', 'Altivez, orgullo', 'Altivez, soberbia o arrogante autoexaltacion — el sentido moralmente negativo de la elevacion. En Isa 2:11 y 2:17, la ''altivez del hombre'' es objetivo de la humillacion divina. Jer 48:29 lo empareja con ga''avah y ga''on en el oraculo contra Moab. ''Altivez'' y ''soberbia'' traducen este juicio moral, e Isa 10:12 lo vincula al corazon orgulloso de Asiria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135239, 'spa', 'Altura (fisica/espacial)', 'Altura fisica o espacial como dimension medible. Solo en Prov 25:3, donde ''los cielos por la altura y la tierra por la profundidad'' ilustran la naturaleza inescrutable del corazon de un rey. El paralelismo con ''profundidad'' confirma un uso puramente espacial y no metaforico, siendo esta una rara instancia concreta de una palabra usada predominantemente para el orgullo moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135240, 'spa', 'Elevación y exaltación', 'Denota alzarse o ser exaltado en diversas conjugaciones. El Peil (pasivo) en Daniel 5:20 describe el corazón de Nabucodonosor «enaltecido» por soberbia. El participio Polel en 4:34 significa «ensalzar» a Dios. El participio Afel en 5:19 describe el poder de «elevar» a personas. El Hitpolel en 5:23 indica «enaltecerse contra» Dios, es decir, autoexaltación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135241, 'spa', 'altura imponente', 'La extensión vertical mensurable de estructuras u objetos visionarios imponentes. El decreto del templo (Esd 6:3) y la imagen de oro (Dn 3:1) lo emplean para medidas arquitectónicas literales, mientras los pasajes del árbol onírico (Dn 4:10, 11, 20) lo extienden simbólicamente: una altura que alcanza el cielo representa la ambición regia desmesurada. El español ''altura'' traduce el término con exactitud.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135248, 'spa', 'Aclamar con gozo, dar voces de júbilo en la adoración, el sentido litúrgico y ce', 'Aclamar con gozo, dar voces de júbilo en la adoración, el sentido litúrgico y celebratorio con 15 apariciones, predominantemente en los Salmos y Esdras. Salmo 47:1 manda ''Aclamad a Dios con voz de triunfo''; Salmo 66:1 y 81:1 abren la adoración con el imperativo hariu. En la dedicación del templo (Esd 3:11-13), el pueblo ''gritó con un gran clamor'' de alegría.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135249, 'spa', 'Levantar un grito fuerte o un clamor de guerra, el sentido de grito bélico conce', 'Levantar un grito fuerte o un clamor de guerra, el sentido de grito bélico concentrado en Josué 6 y las narrativas de conquista, con 20 apariciones. Incluye la dramática marcha séptuple en Jericó, donde se ordena al pueblo ''no gritéis'' (Jos 6:10) hasta la señal, y entonces ''el pueblo gritó con un gran clamor'' (Jos 6:20). También en Jueces 7:21 (la emboscada de Gedeón) y 1 Samuel 17:20, 52 (David y Goliat).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135255, 'spa', 'Dar señal de alarma, tocar un toque de alerta, el sentido militar/ceremonial de ', 'Dar señal de alarma, tocar un toque de alerta, el sentido militar/ceremonial de señalización, centrado en Números 10 y pasajes proféticos de advertencia, con 5 apariciones. Números 10:7 distingue entre ''convocar'' (taq''u, de taqa) y ''dar alarma'' (lo tari''u, de rua); Números 10:9 ordena tocar alarma cuando ataquen los enemigos; Joel 2:1 y Oseas 5:8 usan la alarma como metáfora profética del juicio inminente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135260, 'spa', 'Una única aparición en Hofal (o Polal pasivo) en Isaías 16', 'Una única aparición en Hofal (o Polal pasivo) en Isaías 16:10: ''en las viñas no se levantan voces de alegría (lo yeroa''),'' describiendo el silenciamiento de los gritos de vendimia en los viñedos devastados de Moab. La voz pasiva y el contexto agrícola lo distinguen de los demás sentidos como una forma pasiva del gozo (sentido 2), ahora negada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135267, 'spa', 'Dar voces de triunfo personal, el sentido reflexivo del Hitpael que expresa cele', 'Dar voces de triunfo personal, el sentido reflexivo del Hitpael que expresa celebración exultante sobre los enemigos, con 3 apariciones, todas en los Salmos: Sal 41:11 (''mi enemigo no gritará de triunfo sobre mí''); Sal 60:8 y 108:9 (idénticos: ''sobre Filistea gritaré de triunfo''). El Hitpael añade un matiz reflexivo de regocijo personal dirigido a uno mismo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135282, 'spa', 'correr, moverse velozmente', 'Sentido central Qal de correr físicamente o desplazarse con rapidez a pie, presente en formas finitas, infinitivos e imperativos (63 apariciones). Árabe rakada, coreano 달리다 y suajili -kimbia convergen en esta acepción. La doble carrera de Abraham en Génesis 18 (hacia los visitantes y al rebaño) ejemplifica la urgencia hospitalaria que este verbo conlleva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135283, 'spa', 'guardia real', 'Participio sustantivado הָרָצִים que designa al cuerpo de guardias del rey: corredores que servían como verdugos, centinelas y portaescudos (1 S 22:17; 1 R 14:27-28; 2 R 10:25; 2 Cr 12:10-11). Español y alemán conservan ''corredores / Läufer'', mientras que el inglés cambia a ''guards'', mostrando la deriva semántica de la carrera física a la función militar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135284, 'spa', 'corredor, mensajero', 'Participio activo usado como adjetivo verbal o sustantivo genérico para ''el que corre, un corredor'', distinto del sentido técnico militar. En la narración de la revuelta de Absalón, el vigía identifica a los corredores que se acercan por su modo de correr (2 S 18:24-27). Árabe rākid y coreano 달리는 자 conservan la fuerza participial literal sin la carga institucional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135287, 'spa', 'correos reales persas', 'Correos reales del sistema postal persa: mensajeros oficiales que portaban edictos reales por las provincias del imperio (Est 3:13, 15; 8:10, 14). Sentido institucional distinto de la guardia israelita; las cuatro ocurrencias se agrupan en Ester, y la evidencia multilingüe (español correos, inglés couriers) confirma el desplazamiento hacia la función postal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135299, 'spa', 'hacer correr, perseguir', 'Causativo Hifil: hacer que alguien corra, ya sea persiguiéndolo o llevándolo con urgencia. Gn 41:14 lo usa cuando sacan a José del calabozo ante Faraón; 2 Cr 35:13 describe a los levitas repartiendo porciones con premura. Las siete apariciones se dividen entre persecución hostil (Jer 49:19; Sal 68:31) y despacho urgente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135309, 'spa', 'lanzarse, precipitarse', 'Una única aparición en Nah 2:4 que describe carros de guerra que se precipitan o abalanzan por las calles, extendiendo el sentido de movimiento de la raíz desde corredores humanos a vehículos. Inglés ''they dart'' y español ''corren'' captan el movimiento rápido y errático de los carros en la visión profética de la caída de Nínive.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135326, 'spa', 'Desenvainar, sacar una espada — forma Hifil causativa que expresa la extracción ', 'Desenvainar, sacar una espada — forma Hifil causativa que expresa la extracción de un arma para el combate o la amenaza divina. Éxodo 15:9 cita al enemigo jactándose ''sacaré mi espada''; Levítico 26:33 advierte de la persecución divina con espada desenvainada, y Ezequiel invoca repetidamente la imagen de la espada de Dios desenvainada contra Jerusalén (Ez 5:2, 12; 12:14; 28:7; 30:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135328, 'spa', 'Vaciar o derramar el contenido de un recipiente — ya sea literal (vaciar sacos e', 'Vaciar o derramar el contenido de un recipiente — ya sea literal (vaciar sacos en Gn 42:35, decantar tinajas de vino en Jer 48:12) o metafórico (derramar personas o bendiciones). Malaquías 3:10 promete célebremente que Dios ''derramará'' bendición sin medida, y Zacarías 4:12 describe los dos olivos ''vertiendo'' aceite dorado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135329, 'spa', 'Ser derramado, ser vaciado — forma pasiva (Hofal) del vaciamiento', 'Ser derramado, ser vaciado — forma pasiva (Hofal) del vaciamiento: quedar vacío o ser vertido. En Cantares 1:3 el nombre del amado es ''ungüento derramado'', y Jeremías 48:11 describe a Moab como vino nunca ''trasvasado de vasija en vasija''. Estas dos ocurrencias marcan una forma gramatical distinta que expresa el estado resultante de la acción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135337, 'spa', 'Movilizar, sacar tropas al combate — extensión militar especializada de la metáf', 'Movilizar, sacar tropas al combate — extensión militar especializada de la metáfora de ''extraer''. Se encuentra en Génesis 14:14, donde Abraham ''armó'' a sus 318 siervos entrenados para rescatar a Lot. Esta única ocurrencia preserva un uso arcaico del verbo aplicado a la organización de fuerzas militares.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135343, 'spa', 'Usado adjetival o sustantivamente como ''el pobre, el indigente', 'Usado adjetival o sustantivamente como ''el pobre, el indigente.'' Este uso participial predomina en las 22 ocurrencias, abarcando los contrastes sapienciales de Proverbios entre el rico y el pobre (Pr 10:4; 13:8; 14:20; 22:7), la parábola de Natán sobre la cordera del pobre (2 S 12:1-4), y la preocupación de los Salmos por el vulnerable (Sal 82:3). El español ''pobre'' y el alemán ''Armer'' traducen consistentemente el uso sustantivado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135348, 'spa', 'Participio Hitpael con fuerza pretensiva', 'Participio Hitpael con fuerza pretensiva: hacerse pasar por pobre, fingir pobreza. Proverbios 13:7 empareja esto con su opuesto — ''hay quien se hace rico y no tiene nada'' — creando un proverbio sapiencial sobre la apariencia frente a la realidad. El español ''el que se hace pobre'' capta con precisión el matiz reflexivo-pretensivo de esta forma verbal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135349, 'spa', 'El sentido verbal finito', 'El sentido verbal finito: estar en necesidad, carecer, empobrecerse — describiendo el proceso o estado en lugar de etiquetar a una persona. El Salmo 34:10 declara que los leoncillos ''padecen necesidad y tienen hambre,'' pero a los que buscan al SEÑOR no les falta ningún bien. El español ''empobrecen'' y el alemán ''sind in Mangel'' preservan el dinamismo verbal ausente en el participio sustantivado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135354, 'spa', 'Rut', 'Mujer moabita, figura central del libro de Rut. Tras casarse con un miembro de la familia de Noemí en Moab (Rt 1:4), eligió acompañar a su suegra de regreso a Belén después de la muerte de sus esposos (Rt 1:14, 16, 22). Espigó en el campo de Booz (Rt 2:2, 8), pariente redentor que la tomó por esposa mediante la costumbre del levirato (Rt 4:10-13). Su hijo Obed fue abuelo de David (Rt 4:17, 22), colocándola en el linaje mesiánico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135356, 'spa', 'Misterio, secreto', 'Misterio divino o secreto oculto, accesible únicamente mediante revelación de Dios. Las nueve apariciones se concentran en Daniel 2 y 4, en torno al sueño de Nabucodonosor y la disposición celestial a desvelar lo que la sabiduría humana no penetra. El singular enfatiza un asunto oculto específico (Dan 2:18, 2:27, 4:6), mientras el plural abarca múltiples secretos divinos (Dan 2:28-29).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135361, 'spa', 'Deficiencia y consunción', 'La palabra designa deficiencia en tres contextos. Isaías 10:16 habla metafóricamente de Dios enviando ''flaqueza'' entre los robustos guerreros de Asiria—consunción que contrasta con su gordura o prosperidad. Salmo 106:15 describe juicio divino: ''Les dio lo que pidieron, pero envió flaqueza a su alma''—una imagen inquietante de emaciación espiritual a pesar de abundancia material. Miqueas 6:10 lo aplica a medidas comerciales fraudulentas y reducidas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135365, 'spa', 'Gobernante, dignatario', 'Gobernante, dignatario, potentado — persona que ejerce autoridad politica, de una raiz que significa ''ser de peso''. Siempre en plural, en paralelo con ''reyes'' (melakhim) o ''jueces'' (shoftei eretz), indicando los mas altos escalones del poder humano. Debora los interpela en su triunfo (Jue 5:3) y el salmista los muestra rebelados contra el Senor (Sal 2:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135369, 'spa', 'Hifil causativo', 'Hifil causativo: hacer ancho o ensanchar en extensión espacial. Abarca el ensanchamiento de fronteras (Éx 34:24), territorio (Dt 12:20; 19:8), tiendas (Is 54:2) y expansiones abstractas como agrandar el corazón o el apetito. El español traduce consistentemente ''ensancha/ensanchas,'' reflejando la fuerza causativa activa. Este es el uso dominante en 16 ocurrencias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135370, 'spa', 'Hifil con matices relacionales', 'Hifil con matices relacionales: hacer lugar para alguien, brindando alivio u oportunidad. Isaac nombra un pozo Rejobot porque ''el SEÑOR nos ha dado espacio'' (Gn 26:22). El salmista apela ''me diste anchura en la angustia'' (Sal 4:1). El alemán ''Raum gemacht'' y el español ''hizo ensanchar'' enfatizan la dimensión interpersonal de crear espacio como acto de gracia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135377, 'spa', 'Qal intransitivo', 'Qal intransitivo: hacerse ancho, expandirse o ser agrandado. Ana declara que su boca ''se abrió de par en par'' contra sus enemigos (1 S 2:1), e Isaías profetiza que el corazón ''se ensanchará y se expandirá'' de gozo (Is 60:5). Las formas reflexivas en español y francés (''se ensanchaba'') subrayan la cualidad estativa de este sentido intransitivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135381, 'spa', 'Participio estativo Nifal', 'Participio estativo Nifal: espacioso, amplio. Una sola ocurrencia en Isaías 30:23 describe la tierra de pasto como ''espaciosa'' (nirchav). El árabe ''fasihan'' y el español ''espacioso'' confirman la cualidad adjetival, describiendo un estado de amplitud en lugar de una acción de ensanchar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135383, 'spa', 'Hifil idiomático', 'Hifil idiomático: abrir la boca de par en par, ya sea para hablar, suplicar o devorar. En el Salmo 81:10 Dios invita a Israel a ''abrir bien tu boca y yo la llenaré,'' mientras que en el Salmo 35:21 los enemigos abren la boca de par en par en burla. El español ''ensancharon'' y el alemán ''öffnen weit'' preservan la fisicalidad vívida de la boca abierta como invitación y amenaza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135394, 'spa', 'Un área abierta y amplia cerca de la puerta de la ciudad para reuniones cívicas,', 'Un área abierta y amplia cerca de la puerta de la ciudad para reuniones cívicas, comerciales y sociales. Lot se sienta en la plaza de Sodoma (Gn 19:2); el levita no encuentra hospedaje en la plaza de Guibeá (Jue 19:15-20); Esdras lee la Torá en la plaza frente a la Puerta de las Aguas (Neh 8:1-3). El término aparece en paralelismo poético con ''calles'' y ''mercados'' (Pr 26:13; Cnt 3:2), y en visiones proféticas de vida urbana restaurada (Zac 8:4-5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135417, 'spa', 'Rejob (topónimo)', 'El nombre propio Rejob como topónimo y antropónimo, que abarca una ciudad septentrional cerca de Hamat que servía de punto fronterizo de la Tierra Prometida (Núm 13:21; 2 Sam 10:8), una ciudad levítica en Aser asignada a los gersonitas (Jos 19:28, 30; 21:31; Jue 1:31), un gobernante arameo (2 Sam 8:3, 12) y un levita postexílico (Neh 10:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135421, 'spa', 'anchura, amplitud', 'Extensión lateral: distancia de lado a lado. Empleado sobre todo en especificaciones arquitectónicas del tabernáculo, el templo y los atrios (Éx 25:10; 1 R 6:3; Ez 40-42), emparejado con אֹרֶךְ (longitud). El uso figurado en 1 R 5:9 — ''anchura de corazón'' como vastedad de comprensión — y en Is 8:8 extiende la medida al ámbito intelectual y político.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135432, 'spa', 'Ancho, amplio, espacioso — referido a tierra, muros, ríos y otros elementos espa', 'Ancho, amplio, espacioso — referido a tierra, muros, ríos y otros elementos espaciales. Éxodo 3:8 y Nehemías 9:35 describen la tierra prometida como ''amplia''; Jueces 18:10 y 1 Crónicas 4:40 lo aplican a un territorio extenso y fértil. En Nehemías 3:8 y 12:38 designa una sección de la muralla de Jerusalén (la Muralla Ancha).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135435, 'spa', 'Orgulloso, arrogante (ancho de corazón) — expresión idiomática que significa sob', 'Orgulloso, arrogante (ancho de corazón) — expresión idiomática que significa soberbio o altivo. El Salmo 101:5 declara que Dios no tolerará al ''ancho de corazón'', y Proverbios 21:4 empareja ''ancho de corazón'' con ''ojos altivos'' como señales de pecado. La metáfora espacial proyecta la hinchazón interior como expansión exterior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135442, 'spa', 'Lugar amplio (libertad, alivio) — usado como sustantivo con la preposición para ', 'Lugar amplio (libertad, alivio) — usado como sustantivo con la preposición para significar ''en lugar ancho'', expresando libertad frente a la opresión. El Salmo 119:45 dice ''andaré en libertad'' (en anchura), comunicando la liberación que viene de guardar los preceptos de Dios. La imagen de campo abierto se convierte en metáfora de libertad moral y espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135445, 'spa', 'Codicioso, insaciable (ancho de apetito) — expresión idiomática ''ancho de nephes', 'Codicioso, insaciable (ancho de apetito) — expresión idiomática ''ancho de nephesh (alma/apetito)'' que significa ávido o insaciable. Proverbios 28:25 advierte que el ''ancho de ánimo'' provoca contiendas. Aquí la metáfora espacial de expansión transmite un deseo interior descontrolado, con un juicio moral implícito en la expresión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135449, 'spa', 'Rajab de Jericó', 'Nombre propio de la mujer de Jericó que auxilió a los espías israelitas. Las distintas lenguas transliteran el nombre con variaciones fonéticas menores (español ''Rajab'', inglés ''Rahab''), reflejando su condición de nombre personal y no de palabra traducible. Las cinco referencias pertenecen a la narrativa de Josué (Jos 2:1, 3; 6:17, 23, 25), trazando su papel desde el primer encuentro hasta su liberación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135450, 'spa', 'Topónimo bíblico triple', 'Identifica tres sitios llamados Rejobot: (1) רְחֹבֹת עִיר, cerca de Nínive en Génesis 10:11, posiblemente vinculado al acadio rêbit Ninâ (''plaza de Nínive''); (2) un pozo que Isaac nombró Rejobot en Génesis 26:22, interpretado como «el SEÑOR nos ha dado espacio»; (3) רְחֹבוֹת הַנָּהָר, hogar del rey edomita Saúl en Génesis 36:37 y 1 Crónicas 1:48.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135451, 'spa', 'Nombre propio levítico', 'Nombre propio del nieto de Moisés por línea de Eliezer, presente solo en las genealogías levíticas de Crónicas. Es un nombre teofórico que combina la raíz רָחַב (''ensanchar'') con Yah, expresando que Dios amplía la herencia. Sus cinco menciones (1 Cr 23:17; 24:21; 26:25) lo sitúan en el contexto del servicio del templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135452, 'spa', 'El nombre propio Roboam (Rejav''am), que se refiere exclusivamente al hijo de Sal', 'El nombre propio Roboam (Rejav''am), que se refiere exclusivamente al hijo de Salomón que reinó como rey de Judá tras la disolución de la monarquía unida (c. 930-913 a.C.). Su negativa a aliviar la carga tributaria en Siquem provocó la secesión de las diez tribus del norte (1 R 12:1-17; 2 Cr 10:1-17), y su reinado quedó marcado por la invasión del faraón egipcio Sisac a Jerusalén (1 R 14:25-26; 2 Cr 12:1-9). Su lugar genealógico como hijo de Salomón y padre de Abías ancla la sucesión davídica (1 Cr 3:10; Mt 1:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135456, 'spa', 'Piedras de moler', 'Par de piedras que forman un molino de mano para procesar grano, siempre en forma dual reflejando el mecanismo de dos piedras. Lleva fuertes asociaciones con la vida doméstica y el trabajo femenino (Éx 11:5; Is 47:2). Deuteronomio 24:6 lo considera esencial para la supervivencia, prohibiendo su confiscación como prenda de deuda.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135457, 'spa', 'Nombre propio postexílico', 'Nombre personal postexílico para varios individuos: (1) uno que regresó con Zorobabel en Esdras 2:2 (= Nejum en el paralelo de Nehemías 7:7); (2) un sacerdote llamado רְחֻם en Nehemías 12:3 (posiblemente = Jarim en el versículo 15); (3) un levita que ayudó a reparar el muro en Nehemías 3:17; (4) un firmante del pacto de Nehemías en Nehemías 10:25. El nombre deriva de רָחַם (''tener compasión'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135458, 'spa', 'Oficial persa', 'Identifica a un oficial persa (רְחוּם בְּעֵל-טְעֵם, ''Rehum el canciller'') que, junto con Simsai el escriba, escribió al rey Artajerjes oponiéndose a la reconstrucción de Jerusalén en Esdras 4:8-9, 17, 23. Aunque tradicionalmente se explica a partir del hebreo רָחַם (''compasión''), el nombre puede reflejar el iranio antiguo rukma (''esplendor''), apropiado para un burócrata persa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135459, 'spa', 'Lleno de compasion, profundamente misericordioso, enraizado en רחם (vientre mate', 'Lleno de compasion, profundamente misericordioso, enraizado en רחם (vientre materno), evocando una ternura visceral, casi maternal. Usado casi exclusivamente de Dios como parte de la formula credal רַחוּם וְחַנּוּן (''compasivo y clemente,'' Ex 34:6), que reverbera a traves de los salmos (86:15; 103:8; 111:4; 145:8), los profetas (Joel 2:13; Jonas 4:2) y la literatura posexilica (Neh 9:17, 31; 2 Cr 30:9). La unica aplicacion humana aparece en el Salmo 112:4, donde el justo refleja el caracter divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135463, 'spa', 'Uso adverbial con preposiciones (מֵרָחוֹק ''desde lejos,'' לְמֵרָחוֹק ''a lo lejos,', 'Uso adverbial con preposiciones (מֵרָחוֹק ''desde lejos,'' לְמֵרָחוֹק ''a lo lejos,'' בְּרָחוֹק ''a distancia''), expresando observación, posición o movimiento en relación con un punto remoto. Abraham ''vio el lugar desde lejos'' (Gn 22:4), los hermanos de José ''lo reconocieron a distancia'' (Gn 37:18), Miriam ''se apostó a lo lejos'' (Éx 2:4) y el pueblo ''se mantuvo a distancia'' en el Sinaí (Éx 20:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135464, 'spa', 'Lejanía espacial como adjetivo', 'Lejanía espacial como adjetivo: describe lugares, tierras, pueblos, islas o caminos que están físicamente alejados. Se usa atributivamente (''una tierra lejana,'' Jos 9:6, 9), predicativamente (''¿no está lejos?'') y sustantivadamente (''los lejanos,'' Is 66:19). La preocupación deuteronómica por ''naciones lejanas o cercanas'' (Dt 13:7; 20:15; 29:22) refleja la conciencia de Israel sobre su lugar entre los pueblos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135469, 'spa', 'Lejanía temporal', 'Lejanía temporal: se refiere a acontecimientos, planes o períodos que son antiguos o de hace mucho tiempo. Una extensión rara pero significativa de la metáfora espacial. Isaías 37:26 pregunta: ''¿No has oído? Desde tiempos remotos lo hice; desde días antiguos lo planeé.'' El cambio del espacio al tiempo confirma un auténtico desplazamiento semántico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135476, 'spa', 'Un uso nominal o sustantival que significa ''distancia'' como cantidad medible', 'Un uso nominal o sustantival que significa ''distancia'' como cantidad medible. Atestiguado claramente en Josué 3:4, donde se ordena a Israel mantener un רָחוֹק (distancia) de unos dos mil codos entre ellos y el arca. El español ''distancia'' capta adecuadamente esta función gramatical distinta como sustantivo abstracto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135488, 'spa', 'Oveja hembra', 'Designa a la oveja hembra. Génesis 31:38 enumera ''tus ovejas y tus cabras'' (רְחֵלֶיךָ וְעִזֶּיךָ) en los rebaños de Labán bajo el cuidado de Jacob. Génesis 32:14 detalla 200 ovejas en el regalo de Jacob a Esaú. Cantares 6:6 compara los dientes con ''un rebaño de ovejas'' (כְּעֵדֶר הָרְחֵלִים). Isaías 53:7 emplea ''como oveja ante sus trasquiladores'' (וּכְרָחֵל) en el silencio del siervo sufriente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135489, 'spa', 'El nombre propio Raquel (rakhel, ''oveja''), que designa exclusivamente a la hija ', 'El nombre propio Raquel (rakhel, ''oveja''), que designa exclusivamente a la hija menor de Labán, segunda esposa de Jacob y madre de José y Benjamín. Sus 47 apariciones se concentran en las narrativas patriarcales de Génesis 29-35 (el encuentro junto al pozo, el engaño de la boda, la esterilidad y los nacimientos, el robo de los terafines y su muerte cerca de Efrata). Dos usos proféticos y poéticos extienden su figura: Jeremías la transforma en símbolo de llanto inconsolable (Jer 31:15), y Rut 4:11 la invoca como edificadora de la casa de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135495, 'spa', 'El sentido dominante del Piel', 'El sentido dominante del Piel: Dios o una persona ejerciendo activamente compasión, misericordia y cuidado tierno hacia otro, con 39 apariciones a lo largo de todo el canon. Dios declara a Moisés: ''Tendré compasión del que tendré compasión'' (Éx 33:19); los Salmos lo celebran (Sal 103:13, la metáfora del padre); los profetas lo prometen como fundamento de la restauración tras el exilio (Is 14:1; 49:13; 54:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135500, 'spa', 'El nombre propio simbólico Ruhama, ''la que ha recibido compasión,'' usado en el t', 'El nombre propio simbólico Ruhama, ''la que ha recibido compasión,'' usado en el teatro profético de Oseas (2 apariciones: Os 2:1, 23). Dios revierte el veredicto anterior de Lo-Ruhama (''No-Compadecida,'' Os 1:6) declarando ''Tendré compasión de Lo-Ruhama'' y renombrándola Ruhama. Este uso transforma el verbo en un nombre teológico cargado de significado redentor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135507, 'spa', 'El participio Piel usado como sustantivo', 'El participio Piel usado como sustantivo: ''el compasivo,'' ''el que tiene misericordia,'' describiendo a una persona o a Dios como característicamente misericordioso, con 3 apariciones. Sal 116:5: ''Clemente es el SEÑOR, y justo; nuestro Dios es compasivo.'' Is 49:10: ''el que tiene compasión de ellos los guiará.'' Is 54:10: ''el que tiene misericordia de ti'' habla de fidelidad pactal permanente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135509, 'spa', 'Una única aparición en Qal en el Salmo 18', 'Una única aparición en Qal en el Salmo 18:1 donde el significado pasa de la compasión al amor personal profundo: ''Te amo, oh SEÑOR, fortaleza mía.'' Esta es la única forma Qal de racham en la Biblia hebrea, y lleva una intensidad que supera el ''tener compasión'' del Piel: David expresa una devoción íntima y ferviente, más cercana al amor que a la misericordia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135523, 'spa', 'Pual pasivo', 'Pual pasivo: recibir misericordia, ser objeto de compasión por parte de otro, con 2 apariciones que presentan la perspectiva del receptor. Proverbios 28:13: el que confiesa y abandona el pecado ''alcanzará misericordia.'' Oseas 14:3: el huérfano ''halla compasión'' solo en Dios. La forma Pual es teológicamente significativa: la misericordia no es algo que uno se otorga a sí mismo, sino que se recibe.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135528, 'spa', 'Útero, matriz', 'El útero físico como lugar de concepción y gestación, frecuentemente en frases como ''desde la matriz'' para indicar origen desde el nacimiento. Génesis 49:25 empareja las bendiciones de la matriz con las del pecho en la bendición patriarcal. Funciona tanto literalmente (Jue 5:30; Pr 30:16) como en expresiones temporales-teológicas que subrayan el cuidado divino desde antes de nacer (Is 46:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135529, 'spa', 'Compasión o misericordias como cualidad moral-teológica, especialmente de Dios h', 'Compasión o misericordias como cualidad moral-teológica, especialmente de Dios hacia su pueblo. El sentido dominante (38 de 40 apariciones), usado en oraciones y alabanzas: ''Caigamos en manos del SEÑOR, porque sus misericordias son grandes'' (2 S 24:14), y ''conforme a tu gran compasión borra mis transgresiones'' (Sal 51:1). Emparejado con chesed en Oseas 2:21 y Salmo 40:12, configurando los dos pilares gemelos de la fidelidad divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135541, 'spa', 'Sentimientos viscerales profundos localizados físicamente en las entrañas, prese', 'Sentimientos viscerales profundos localizados físicamente en las entrañas, preservando el vínculo etimológico con rechem (útero). En Génesis 43:30, las entrañas de José ''se conmovieron'' (nikhmeru) hacia Benjamín, un impulso corporal e incontrolable de amor fraternal. En 1 Reyes 3:26, las entrañas de la verdadera madre ''ardieron'' por su hijo ante Salomón. Este sentido conserva de manera llamativa la dimensión somática del término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135559, 'spa', 'El útero o vientre físico como órgano de concepción y nacimiento, empleado en va', 'El útero o vientre físico como órgano de concepción y nacimiento, empleado en varios modismos teológicos. Central en la fórmula de consagración del primogénito peter rechem, ''el que abre la matriz'' (Éx 13:2, 12; Nm 18:15). Expresa el control soberano de Dios sobre la fertilidad: cerrar (Gn 20:18) y abrir (Gn 29:31; 30:22) la matriz. En textos proféticos y poéticos, ''desde el vientre'' señala la elección divina antes del nacimiento (Jer 1:5; Sal 22:10). El sustantivo cognado rachamim (''compasión'') deriva de esta raíz, vinculando la experiencia corporal materna con la misericordia divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135574, 'spa', 'Bañar el cuerpo entero en agua, generalmente intransitivo o reflexivo', 'Bañar el cuerpo entero en agua, generalmente intransitivo o reflexivo. Este es abrumadoramente el sentido de purificación levítica: tras el contacto con impureza, uno ''se lavará en agua'' (Lv 15:5 y docenas de mandatos similares). La hija del faraón ''bajó a bañarse'' al Nilo (Éx 2:5) y Betsabé estaba ''bañándose'' cuando David la vio (2 S 11:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135575, 'spa', 'Lavar un objeto específico, una parte del cuerpo u otra persona con agua', 'Lavar un objeto específico, una parte del cuerpo u otra persona con agua: el uso transitivo. Lavar los pies es el ejemplo paradigmático: Abraham ofrece agua para los pies de sus huéspedes (Gn 18:4), un gesto repetido a lo largo de las narrativas patriarcales (Gn 19:2; 24:32; 43:24). El verbo también cubre el lavado de las entrañas y patas sacrificiales sobre el altar (Lv 1:9, 13) y el lavado de manos o rostro (Gn 43:31; Éx 30:19-21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135589, 'spa', 'La forma pasiva (tronco Pual)', 'La forma pasiva (tronco Pual): ser lavado o recibir lavamiento. Solo dos ocurrencias claras: la devastadora imagen de Ezequiel de Jerusalén como una recién nacida que ''no fue lavada en agua'' al nacer (Ez 16:4), y el retrato de Proverbios 30:12 de una generación ''no lavada de su inmundicia.'' Estos raros pasivos llevan un peso teológico especial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135596, 'spa', 'Una única aparición en Job 9', 'Una única aparición en Job 9:30 donde Job habla hipotéticamente: ''Si me lavara con aguas de nieve.'' Este es el tronco Hitpael (reflexivo intensivo), la única forma de este tipo de רָחַץ en la Biblia hebrea. Intensifica el sentido reflexivo: no meramente bañarse sino limpiarse a fondo con el agua más pura imaginable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135619, 'spa', 'El sentido estativo Qal', 'El sentido estativo Qal: estar lejos, hallarse a distancia. Se usa para la lejanía geográfica (Dt 12:21; 14:24), la distancia emocional o relacional (Pr 19:7; Job 30:10) y el abandono teológico: la angustiosa pregunta de por qué Dios se mantiene lejos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135620, 'spa', 'El causativo Hifil y el transitivo Piel', 'El causativo Hifil y el transitivo Piel: alejar, apartar, enviar a la distancia. Job 11:14 exhorta a apartar la iniquidad de la propia tienda; Job 19:13 lamenta que Dios ha alejado a sus hermanos de él. Salmo 103:12 alcanza la cúspide de este sentido: ''Cuanto está lejos el oriente del occidente, hizo alejar de nosotros nuestras rebeliones.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135621, 'spa', 'Formas de infinitivo y participio usadas adverbialmente para expresar el concept', 'Formas de infinitivo y participio usadas adverbialmente para expresar el concepto de ''a lo lejos'' o ''a gran distancia'' como modo o extensión. Agar se sienta ''a lo lejos'' de Ismael (Gn 21:16); la tienda de reunión se coloca ''lejos'' del campamento (Éx 33:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135626, 'spa', 'Movimiento intransitivo activo', 'Movimiento intransitivo activo: irse lejos, retirarse, huir a la distancia. Salmo 55:7 clama ''me alejaría volando''; Josué 8:4 posiciona un grupo de emboscada a cierta distancia. Se implica una partida volitiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135629, 'spa', 'Con fuerza moral o conductual', 'Con fuerza moral o conductual: mantenerse lejos de, abstenerse. Eclesiastés 3:5 habla de un tiempo ''para abstenerse de abrazar''; Ezequiel 8:6 implica ser expulsado lejos del santuario por las abominaciones. Denota una abstención deliberada y con propósito.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135640, 'spa', 'En Salmo 103', 'En Salmo 103:12 el verbo aparece en una construcción comparativa — ''cuanto está lejos el oriente del occidente'' — midiendo la extensión infinita del perdón de Dios. Estira el verbo espacial hasta convertirlo en una metáfora teológica de la remoción total del pecado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135647, 'spa', 'En Isaías 26', 'En Isaías 26:15 el verbo adquiere el sentido de ensanchar o extender fronteras: ''extendiste todos los confines de la tierra.'' Señala un desplazamiento semántico del distanciamiento a la expansión territorial, una aplicación única del alcance espacial de la raíz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135667, 'spa', 'Ser estrellado (pasivo)', 'Ser estrellado o despedazado (Pual pasivo), describiendo a las víctimas de destrucción violenta en guerra. En Isa 13:16, los niños de Babilonia ''serán estrellados'' ante los ojos de sus padres. Os 10:14 y 13:16 aplican la imagen a la caída de Samaria, y Nah 3:10 a Nínive. La voz pasiva subraya que son atrocidades sufridas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135669, 'spa', 'Estrellar (activo)', 'Estrellar o despedazar (Piel activo), el acto deliberado de destrozar. En 2 Re 8:12, Eliseo llora al prever lo que Hazael hará a los niños de Israel: ''los estrellarás.'' Isa 13:18 atribuye la acción a ejércitos invasores cuyos arcos abaten a los jóvenes. El español ''estrellarás'' capta la agencia directa y personal del perpetrador en este acto horrendo de guerra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135674, 'spa', 'Contienda interpersonal general, riña o disputa sin marco jurídico formal', 'Contienda interpersonal general, riña o disputa sin marco jurídico formal. Los pastores de Isaac disputan con los pastores de Gerar por los pozos (Gn 26:20-22); Israel contiende con Moisés junto a las aguas (Éx 17:2); Nehemías reprende a los nobles por la usura (Neh 13:11, 17, 25). Se trata de conflicto no judicial, de palabra más que de tribunal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135676, 'spa', 'Alegato jurídico, defensa o litigio formal', 'Alegato jurídico, defensa o litigio formal: defender una causa o abogar en un contexto legal o cuasi-legal. Cuando el padre de Gedeón dice ''que Baal contienda por sí mismo'' (Jue 6:31-32), el verbo tiene fuerza forense. David apela a Dios: ''Defiende mi causa'' (Sal 35:1; 1 S 24:15). El pleito profético — ''Jehová tiene pleito con su pueblo'' (Mi 6:1-2) — representa la cúspide teológica de este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135683, 'spa', 'Una única aparición problemática en 1 Samuel 15', 'Una única aparición problemática en 1 Samuel 15:5 donde las traducciones divergen marcadamente del significado esperado de riv. El contexto indica ''puso emboscada,'' lo cual probablemente refleja un asunto textual o de análisis morfológico: el verbo vayyarev aquí podría derivar de una raíz distinta (rav/''arav, emboscar) en lugar de riv (contender).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135693, 'spa', 'La forma participial del Hifil usada sustantivamente para designar al ''adversari', 'La forma participial del Hifil usada sustantivamente para designar al ''adversario'' u ''oponente'': el que contiende en contra. En 1 Samuel 2:10 los adversarios de Jehová serán quebrantados; en Oseas 4:4 ''que nadie contienda'' (participio como nombre de agente). El paso de la acción verbal al nombre de agente es claro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135712, 'spa', 'El sustantivo riv (misma forma radical) usado sustantivamente para designar una ', 'El sustantivo riv (misma forma radical) usado sustantivamente para designar una disputa, riña o pleito como entidad abstracta. Job 31:13: ''si hubiere rechazado la causa de mi siervo''; Proverbios 25:9: ''debate tu causa con tu prójimo.'' Solo dos apariciones se agrupan aquí, pero la función nominal es distinta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135732, 'spa', 'Contienda, riña u hostilidad entre partes', 'Contienda, riña u hostilidad entre partes. Génesis 13:7 introduce este sentido con la disputa entre los pastores de Abram y los de Lot por los pastos, y Éxodo 17:7 da nombre al lugar ''Meriba'' por la contienda del pueblo. Proverbios es especialmente rico en este uso: ''el comienzo de la contienda es como soltar aguas'' (17:14), ''el hombre iracundo suscita contiendas'' (15:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135733, 'spa', 'Una disputa o controversia más amplia que una riña privada pero no necesariament', 'Una disputa o controversia más amplia que una riña privada pero no necesariamente un proceso judicial formal: una contención pública o asunto en litigio. Deuteronomio 17:8 habla de casos ''demasiado difíciles de juzgar, ya sea cuestión de homicidio, pleito o disputa (riv),'' enumerándolo junto al ámbito estrictamente judicial pero distinto de él. Deuteronomio 19:17 y 25:1 posicionan riv de manera similar como un asunto en disputa que requiere resolución.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135734, 'spa', 'Una causa legal formal, pleito o litigio presentado ante una autoridad para su a', 'Una causa legal formal, pleito o litigio presentado ante una autoridad para su adjudicación. Este sentido aparece prominentemente en Éxodo 23:3, 6 (no pervertir la justicia en la causa del pobre), 1 Samuel 24:15 (David encomienda su causa a Jehová como juez) y Job 29:16 (''investigaba la causa del desconocido''). El español distingue este sentido con ''causa'' (causa legal) y ''pleito.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135775, 'spa', 'La frase técnica cúltica reyaj nijoaj (''aroma agradable'') describe la fragancia ', 'La frase técnica cúltica reyaj nijoaj (''aroma agradable'') describe la fragancia ascendente de un holocausto que agrada a Dios. Con 46 apariciones, domina Levítico, Números y Éxodo 29. La frase aparece por primera vez en el altar de Noé (Gn 8:21) y se convierte en el vocabulario estándar para el sacrificio aceptable a lo largo de toda la legislación mosaica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135778, 'spa', 'La fragancia naturalmente agradable de una persona, planta o aceite perfumado, u', 'La fragancia naturalmente agradable de una persona, planta o aceite perfumado, usada en contextos poéticos y proféticos. El Cantar de los Cantares concentra estas apariciones: el nardo de la amada (1:12), el aroma de las mandrágoras (7:13) y la fragancia del Líbano comparada con Israel restaurado en Oseas 14:7. Marca un desplazamiento del vocabulario ritual al sensorial y estético.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135779, 'spa', 'Un olor general o neutro, a veces incluso desagradable por implicación, usado fu', 'Un olor general o neutro, a veces incluso desagradable por implicación, usado fuera de contextos cúlticos. En Éxodo 5:21 los israelitas lamentan ''habéis hecho que nuestro olor apeste'' ante el faraón, un uso figurado para la reputación. Job 14:9 habla de un árbol que revive con el mero olor del agua. Estos pasajes muestran a reyaj en su uso más versátil, extendiéndose del olor físico a la percepción social.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135796, 'spa', 'Vacuidad, vanidad, en vano', 'Vacuidad abstracta, vanidad o futilidad, especialmente en la construcción adverbial lərīq que significa ''en vano, sin propósito''. Dios advierte a Israel que su fuerza se agotará lārīq — para nada (Lv 26:16, 20). El Siervo en Isaías 49:4 se lamenta de haber trabajado ''para vacuidad''. El salmista pregunta por qué las naciones conspiran rīq — en rabia fútil (Sal 2:1), y si purificar el corazón fue ''en vano'' (Sal 73:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135799, 'spa', 'Vacío (concreto, físico)', 'Vacuidad concreta y física — estar desprovisto de contenido o sustancia. En Jeremías 51:34, Nabucodonosor ha devorado a Jerusalén y la ha dejado ''vacía'', como un recipiente despojado de su contenido. El árabe fārighan (''vacío, hueco''), el hindi khālī (''vacío'') y el coreano bin (''vacío'') apuntan a una vacancia tangible y espacial, no a una futilidad abstracta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135802, 'spa', 'Fisicamente vacio o vacante', 'Fisicamente vacio o vacante: describe recipientes, espacios o cosas desprovistas de contenido. La cisterna donde fue arrojado Jose estaba ''vacia, sin agua'' (Gen 37:24); el sueno de Faraon presentaba siete espigas vacias (Gen 41:27); los soldados de Gedeon llevaban cantaros vacios (Jue 7:16). Las traducciones convergen: espanol ''vacio,'' todas apuntan a una vacuidad literal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135805, 'spa', 'Cosas vanas, actividades futiles', 'Cosas vanas, actividades futiles: la extension abstracta donde la vacuidad caracteriza no a las personas sino a sus ocupaciones. ''El que persigue cosas vanas carece de entendimiento'' (Pr 12:11; 28:19). Este sentido captura la dimension abstracta y moral-filosofica donde la vacuidad se convierte en vanidad y futilidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135806, 'spa', 'Personas indignas, ociosas o temerarias', 'Personas indignas, ociosas o temerarias: una transferencia moral de la vacuidad fisica al caracter humano. Abimelec contrato ''hombres indignos y temerarios'' (Jue 9:4), Jefte reunio ''hombres vacios'' (Jue 11:3), y Mical acuso a David de exponerse ante ''los vacios'' (2 Sam 6:20). El sentido selecciona un vacio de caracter moral mas que fisico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135812, 'spa', 'Vacío, con las manos vacías — en estado de no tener nada en las manos ni posesio', 'Vacío, con las manos vacías — en estado de no tener nada en las manos ni posesiones. Este sentido concreto domina el uso: Jacob habría sido despedido ''vacío'' por Labán (Gn 31:42); Israel no debe presentarse ante el SEÑOR con las manos vacías (Éx 23:15; 34:20; Dt 16:16); un siervo liberado no debe ser enviado vacío (Dt 15:13); Noemí regresa a Belén ''vacía'' (Rut 1:21; 3:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135814, 'spa', 'Sin causa, en vano — extensión abstracta del vacío al ámbito del motivo o el res', 'Sin causa, en vano — extensión abstracta del vacío al ámbito del motivo o el resultado. En el Salmo 7:4 el salmista niega haber despojado ''a mis adversarios sin causa'', y el Salmo 25:3 habla de quienes ''obran con traición sin razón''. Es el paso figurado del vacío físico a la falta de propósito o justificación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135817, 'spa', 'Pobreza material', 'Pobreza material e indigencia económica, la condición de carecer de recursos y ser económicamente vulnerable. Las cinco apariciones se agrupan en Proverbios, donde se opone a la riqueza (Pr 30:8) y a la ''ciudad fuerte'' protectora del rico (10:15). La literatura sapiencial presenta esta pobreza como resultado moral de la negligencia o la insensatez, no como mera circunstancia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135819, 'spa', 'Tierno, joven, delicado — de constitución física suave, frágil o inmadura, aplic', 'Tierno, joven, delicado — de constitución física suave, frágil o inmadura, aplicado a personas, animales o plantas. Los hijos de Jacob son ''tiernos'' y no pueden ser forzados (Gn 33:13), Abraham escoge un becerro ''tierno y bueno'' (Gn 18:7), los ojos de Lea son descritos como רַכּוֹת — ''tiernos'' o ''suaves'' en contraste con la belleza de Raquel (Gn 29:17), y Salomón es calificado de joven e inexperto (1 Cr 22:5; 29:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135820, 'spa', 'Suave, apacible (del habla o la manera) — cualidad de las palabras o la persuasi', 'Suave, apacible (del habla o la manera) — cualidad de las palabras o la persuasión, no de la constitución física. Tres ocurrencias en la literatura sapiencial celebran la fuerza paradójica de la suavidad: ''la respuesta suave aparta la ira'' (Pr 15:1), ''la lengua suave quebranta el hueso'' (Pr 25:15), y Leviatán pregunta burlonamente si ''hablará palabras suaves'' a su captor (Job 41:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135825, 'spa', 'Pusilánime, tímido — dimensión emocional de la blandura aplicada a la resolución', 'Pusilánime, tímido — dimensión emocional de la blandura aplicada a la resolución del guerrero. Una sola ocurrencia en Deuteronomio 20:8 ordena a los oficiales de Israel despedir al soldado ''medroso y de corazón blando'' (רַךְ הַלֵּבָב) antes de la batalla, para que su cobardía no se contagie.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135829, 'spa', 'Participio Qal usado como sustantivo', 'Participio Qal usado como sustantivo: jinete o auriga, tanto en singular como en plural, incluyendo el título teofánico «el que cabalga los cielos». Éx 15:1 empareja caballo y רֹכֵב en triunfo; Dt 33:26 eleva la imagen a escala cósmica: Dios cabalga los cielos en majestad. Am 2:15 advierte que el jinete no escapará.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135832, 'spa', 'Verbo finito Qal básico que significa montar y cabalgar sobre un animal, un carr', 'Verbo finito Qal básico que significa montar y cabalgar sobre un animal, un carro o, metafóricamente, las nubes. En Gn 24:61 Rebeca monta un camello; Lv 15:9 trata como ritualmente significativa la montura sobre la que alguien cabalga. Los términos «cabalgar/cabalgó» expresan el acto físico de sentarse a horcajadas y viajar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135839, 'spa', 'Hifil causativo que significa hacer montar a alguien o sentar a una persona sobr', 'Hifil causativo que significa hacer montar a alguien o sentar a una persona sobre una cabalgadura, generalmente en contextos de entronización, honor o transporte deliberado. Gn 41:43 relata que Faraón hizo montar a José en el segundo carro; 1 R 1:33 y 1:38 narran la procesión de unción de Salomón sobre la mula de David.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135865, 'spa', 'Uso especializado del Hifil que significa cargar o colocar mercancía inanimada s', 'Uso especializado del Hifil que significa cargar o colocar mercancía inanimada sobre un animal para transportarla, distinguido del causativo personal por su objeto. En 2 S 6:3 y 1 Cr 13:7, el arca de Dios es colocada sobre un carro nuevo. El hebreo solo hace la distinción entre carga de personas y carga de objetos por el contexto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135884, 'spa', 'carro de guerra', 'Vehículo bélico con ruedas o fuerza colectiva de carros de un ejército: los carros de Faraón (Éx 14:7), los novecientos carros de hierro de Sísara (Jue 4:3), el cuerpo de carros de Salomón (1 R 10:26). A menudo emparejado con caballería (פָּרָשִׁים) y caballos (סוּסִים). El sentido colectivo es más frecuente que la referencia individual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135899, 'spa', 'piedra de molino superior', 'La piedra superior del molino de mano que ''cabalga'' sobre la inferior: extensión metafórica de la raíz ר-כ-ב (''montar''). Dt 24:6 prohíbe tomarla en prenda; Jue 9:53 narra a la mujer que arrojó una sobre Abimelec; 2 S 11:21 rememora el episodio. Solo tres apariciones, confirmadas por español piedra de molino y coreano 맷돌/윗돌.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135930, 'spa', 'El nombre propio Recab (רֵכָב), llevado por varios personajes bíblicos', 'El nombre propio Recab (רֵכָב), llevado por varios personajes bíblicos: (a) Recab hijo de Rimón, quien junto con su hermano Baaná asesinó a Is-boset (2 Sam 4:2–12); (b) el ancestro epónimo de los recabitas, cuyo descendiente Jonadab se unió a la purga de Jehú (2 Re 10:15, 23) y cuya comunidad Jeremías elogió por su fidelidad al pacto (Jer 35:6–19); (c) Recab padre de Malquías (Neh 3:14). Las traducciones al español incluyen Recab, Rejav y Rekav.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135935, 'spa', 'Especialista militar montado', 'La palabra se refiere a especialistas militares que controlan caballos en combate, con el contexto determinando si son aurigas o caballería. En 1 Reyes 22:34 y 2 Crónicas 18:33, Acab ordena ''a su conductor'' dar vuelta el carro cuando es herido—claramente un auriga. Segunda de Reyes 9:17 lo usa para ''un jinete'' enviado como explorador, distinguido de soldados que van en carros. Ambos usos identifican militares profesionales montados.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135937, 'spa', 'Clan recabita', 'Identifica a los recabitas (בֵּית הָרֵכָבִים o בְּנֵי בֵית-הָרֵכָבִים), un clan descendiente de Recab hijo de Jonadab. Las cuatro apariciones se encuentran en Jeremías 35:2-3, 5, 18, donde Dios ordena a Jeremías ponerlos a prueba ofreciéndoles vino, que ellos rechazan, explicando su voto ancestral de abstenerse del vino, no construir casas ni plantar viñas, manteniendo una existencia nómada perpetua.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135940, 'spa', 'El término amplio para propiedad poseída, posesiones o riqueza acumulada de cual', 'El término amplio para propiedad poseída, posesiones o riqueza acumulada de cualquier tipo — ganado, bienes raíces y activos materiales pertenecientes a una persona o familia. Las posesiones de Abram al salir de Harán (Gn 12:5), la riqueza demasiado grande que impedía a Abram y Lot habitar juntos (Gn 13:6), y las propiedades reales supervisadas por los administradores de David (1 Cr 27:31) emplean este sentido general. El español ''hacienda'' y ''posesión'' reflejan fielmente la amplitud de este campo semántico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135942, 'spa', 'Bienes muebles, pertenencias o botín adquirido por migración, viaje o conquista ', 'Bienes muebles, pertenencias o botín adquirido por migración, viaje o conquista militar, distinguido de la riqueza establecida por su naturaleza portátil y frecuentemente transaccional. El botín del campamento moabita (2 Cr 20:25), los bienes proporcionados a los exiliados que regresaban por sus vecinos (Esd 1:4, 6), y las riquezas distribuidas por el rey del norte (Dn 11:24) llevan este matiz. El árabe ghanima (botín) y el español ''bienes'' y ''riquezas'' captan esta dimensión de riqueza en movimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135964, 'spa', 'Calumnia, difamación', 'La actividad o práctica abstracta de difundir chismes maliciosos y calumnias. En Jer 6:28, el pueblo es caracterizado como ''andadores de calumnia,'' y Ez 22:9 condena a ''hombres de calumnia,'' delatores que derraman sangre. El hebreo construye con ''hombres de'' o ''andadores de,'' manteniendo el foco en la práctica más que en el individuo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135966, 'spa', 'Calumniador, chismoso', 'Un calumniador o chismoso: el agente humano que difunde habladurías. El Código de Santidad (Lev 19:16) prohíbe andar ''como chismoso'' entre el pueblo, y Proverbios advierte dos veces contra el chismoso que no guarda secretos (11:13; 20:19). El uso proverbial lo convierte en un defecto de carácter paradigmático que socava la confianza comunitaria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135969, 'spa', 'Ser blando, tierno', 'Ser o volverse blando, tierno o débil: suavidad física (palabras más suaves que el aceite, Sal 55:21; herida sin tratar, Isa 1:6 en Pual) y estados emocionales. El corazón ''se ablanda'' por timidez ante enemigos (Dt 20:3; Isa 7:4; Jer 51:46) o por ternura penitente ante Dios (2 Re 22:19 = 2 Cr 34:27).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135971, 'spa', 'Ablandar, debilitar', 'El causativo Hifil: ablandar, provocar desfallecimiento de la resolución. Atestiguado solo en Job 23:16, donde Job confiesa ''Dios ha ablandado mi corazón'' (הֵרַךְ לִבִּי). El contexto —Job abrumado por el poder divino— señala a un agente externo que socava el valor humano, contraparte causativa de la condición interna del Qal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135977, 'spa', 'Comerciante, mercader — tratante profesional derivado del participio Qal de raka', 'Comerciante, mercader — tratante profesional derivado del participio Qal de rakal (''ir de un lugar a otro comerciando''). Concentrado en Ezequiel 27, donde Tiro es descrita como ciudad de mercaderes cuyos socios comerciales se enumeran extensamente (Ez 27:13, 15, 17, 22-24). También aparece en Nehemías para los mercaderes a las puertas de Jerusalén (Neh 3:31-32; 13:20), en 1 Reyes 10:15 para los ingresos de Salomón por los comerciantes, y poéticamente en Cantares y Nahúm.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135988, 'spa', 'Comercio y mercancía', 'Designa la actividad comercial o las mercancías. En Ezequiel 28:5, 16, 18, ''tu comercio'' (רְכֻלָּתְךָ) describe la actividad mercantil de Tiro que condujo a la riqueza y al orgullo. Ezequiel 26:12 habla de saquear ''tus mercancías'' (רְכֻלָּתֵךְ). Las cuatro apariciones se encuentran en los extensos oráculos de Ezequiel contra Tiro (capítulos 26-28), enfatizando su identidad como imperio comercial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135992, 'spa', 'Adquirir bienes muebles', 'Adquirir o acumular bienes muebles — ganado, siervos y posesiones — mediante esfuerzo económico deliberado a lo largo del tiempo. Restringido a las narrativas patriarcales de Génesis (12:5; 31:18; 36:6; 46:6), siempre describe la reunión de riqueza transportable. El emparejamiento constante con רְכֻשׁ como acusativo cognado subraya el carácter intencional y progresivo de la acumulación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135993, 'spa', 'Corceles de élite', 'Designa caballos selectos o corceles. En 1 Reyes 4:28, son los caballos (רֶכֶשׁ וְסוּסִים, ''corceles y caballos'') para los carros de Salomón. Ester 8:10, 14 especifica monturas reales (הָרֶכֶשׁ, בְּנֵי הָרַמָּכִים, ''los corceles, hijos de las yeguas de cría'') usadas por los correos que portaban el decreto que revocaba la conjura de Amán. Miqueas 1:13 ordena uncir el corcel al carro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135994, 'spa', 'Ram', 'Nombre propio que identifica a: (a) un ancestro de David en la línea de Judá a través de Hezrón (Rut 4:19; 1 Cr 2:9-10), (b) un hijo de Jerameel (1 Cr 2:25, 27) y (c) la familia de Elihú en Job 32:2. La Septuaginta lo traduce como Arrán y Ram. Todas las lenguas modernas lo preservan sin alteración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135996, 'spa', 'Arrojar o disparar', 'Expresa el acto de arrojar o disparar proyectiles. En Exodo 15:1, 21 el cantico de victoria proclama que Dios ''ha arrojado caballo y jinete al mar'' (רָמָה בַיָּם). Salmo 78:9 describe a los efrateos como ''flecheros del arco'' (רוֹמֵי־קֶשֶׁת), guerreros que sin embargo retrocedieron. Jeremias 4:29 presenta ciudades huyendo de los arqueros.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (135997, 'spa', 'Engañar, embaucar', 'Piel: engañar, embaucar o actuar con traición contra alguien. Siempre interpersonal, implicando violación de confianza. Pasajes clave incluyen el engaño nupcial de Labán a Jacob (Gn 29:25), la artimaña gabaonita (Jos 9:22), el encubrimiento de David por Mical (1 Sam 19:17) y el lamento de traición en Lam 1:19.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136003, 'spa', 'Estar alto, alzada', 'Participio femenino Qal: estar alto o alzado, describiendo una «mano alzada» como postura de desafío. En Núm 15:30 la expresión «con mano alzada» indica un pecado deliberado y descarado contra YHWH. Esta forma probablemente pertenece a una raíz homónima distinta (ramah I, «estar alto») y no a la raíz de engaño.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136004, 'spa', 'Arrojar, echar (personas)', 'Arrojar o lanzar personas a un lugar de castigo — el sentido dominante en las narraciones cortesanas de Daniel. Se usa repetidamente para echar hombres al horno de fuego de Nabucodonosor (Dn 3:6, 11, 15, 20, 21, 24) y al foso de los leones de Darío (Dn 6:8, 13, 17, 25). El Hithpe''el pasivo (''será arrojado'') aparece en los decretos reales que amenazan con castigo, mientras que el Pe''al activo describe el lanzamiento mismo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136006, 'spa', 'Colocar, poner', 'Colocar o poner en posición, un sentido Pe''il (pasivo) más sereno y distinto del lanzamiento violento. Daniel 7:9 lo emplea para los tronos que son ''puestos'' o ''colocados'' en la escena del tribunal celestial — un posicionamiento deliberado y solemne, no un lanzamiento forzado. El español ''fueron puestos'' capta este matiz digno, contrastando marcadamente con el arrojamiento punitivo del sentido principal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136007, 'spa', 'Imponer (figurado)', 'Imponer o cargar figuradamente, específicamente la carga de tributo o impuestos. Esdras 7:24 usa el infinitivo para describir la prohibición de ''imponer'' tributo a los siervos del templo. El español ''imponer'' y el inglés ''to impose'' reflejan la extensión metafórica: lo que se ''arroja sobre'' alguien se convierte en una obligación o carga financiera en vez de un proyectil físico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136013, 'spa', 'santuario cultual elevado', 'Plataforma cultual elevada o santuario construido para culto ilícito, funcionando como término técnico en la condena profética. Ezequiel 16:24-39 emplea esta palabra cuatro veces, describiendo a Jerusalén personificada que edifica santuarios elevados (en paralelo con גַּב, ''montículo'') en cada esquina para prácticas idolátricas. La aparición en 1 Samuel 22:6 puede aludir a una altura geográfica genérica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136014, 'spa', 'El nombre propio Ramá, que designa una ciudad benjaminita en la frontera con Efr', 'El nombre propio Ramá, que designa una ciudad benjaminita en la frontera con Efraín, situada en el camino de la cordillera central al norte de Jerusalén. Funciona como sede profética de Samuel (1 S 1:19; 2:11; 7:17; 25:1), punto estratégico militar en el conflicto entre Asá y Baasa (1 R 15:17-22 = 2 Cr 16:1-6), y lugar de lamento profético (Jer 31:15; citado en Mt 2:18). La forma alterna ha-Ramathaim aparece en 1 Samuel 1:1, señalando posiblemente la misma localidad o una variante dual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136023, 'spa', 'Gusano, larva', 'Sustantivo colectivo o singular para gusanos o larvas que se alimentan de materia en descomposición, sirviendo en la Biblia hebrea como símbolo de putrefacción, mortalidad y fragilidad humana. Job 7:5 describe la carne «vestida de gusanos» y Job 17:14 se dirige al gusano como pariente. Isaías 14:11 empareja rimmah con tole''ah como destino degradante de los tiranos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136028, 'spa', 'El fruto de la granada, ya sea comido, exprimido para obtener jugo (Cnt 8', 'El fruto de la granada, ya sea comido, exprimido para obtener jugo (Cnt 8:2), o sirviendo como modelo para los adornos decorativos en las vestiduras sacerdotales (Éx 28:33-34; 39:24-26) y los capiteles de las columnas del templo (1 R 7:18-20; Jer 52:22-23). Este sentido abarca 28 apariciones. Las traducciones lo rinden uniformemente como ''granadas'' (español), ''grenades'' (francés), ''Granatäpfel'' (alemán), señalando al fruto mismo o su representación ornamental.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136036, 'spa', 'El árbol de granada como planta viva o cultivo agrícola, distinguido de su fruto', 'El árbol de granada como planta viva o cultivo agrícola, distinguido de su fruto en contextos que describen huertos, jardines o pérdida de cosechas. Saúl se sienta bajo un granado en Migrón (1 S 14:2), el jardín de la amada es un ''paraíso de granados'' (Cnt 4:13), y Joel lamenta su marchitez (1:12). El español distingue claramente entre ''granado'' (árbol) y ''granada'' (fruto), una distinción que el hebreo no marca morfológicamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136042, 'spa', 'Deidad aramea', 'Este nombre divino designa a la deidad aramea de la tormenta cuyo templo estaba en Damasco. Las tres ocurrencias en 2 Reyes 5:18 aparecen en la petición de Naamán a Eliseo: cuando el rey sirio se apoya en el brazo de Naamán en ''la casa de Rimón'' y se inclina, ¿debe Naamán inclinarse también? La repetición enfatiza el dilema del converso—el deber político requiriendo gestos en un templo pagano. Rimón probablemente se equiparaba con Hadad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136043, 'spa', 'Benjamita, padre de regicidas', 'El nombre identifica a un benjamita cuyos hijos cometieron regicidio. Segunda de Samuel 4:2, 5 y 9 mencionan ''los hijos de Rimón beerotita''—Recab y Baana, quienes sirvieron como saqueadores bajo Is-boset pero lo asesinaron traicioneramente durante su descanso del mediodía. Cuando trajeron la cabeza cortada a David esperando alabanza, él los pronunció culpables de derramar sangre inocente y los hizo ejecutar. El patronímico ''beerotita'' vincula a Rimón con Beerot en Benjamín.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136044, 'spa', 'Rimón (topónimo)', 'El topónimo Rimón, que designa múltiples ciudades israelitas: una en Simeón/sur de Judá emparejada con Aín (Jos 15:32; 19:7; 1 Cr 4:32; Zac 14:10), una ciudad levítica en Zabulón (Jos 19:13; 1 Cr 6:62) y la «Peña de Rimón» en Benjamín donde los sobrevivientes hallaron refugio (Jue 20:45, 47; 21:13). Significa literalmente «granada».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136050, 'spa', 'Arma de acometida con asta larga y punta de metal, usada en combate cuerpo a cue', 'Arma de acometida con asta larga y punta de metal, usada en combate cuerpo a cuerpo y enumerada entre el equipamiento militar estándar. En español se traduce sistemáticamente como ''lanza''. Aparece frecuentemente emparejada con חֶרֶב (espada) y מָגֵן (escudo) en inventarios militares (2 Cr 11:12; 14:7; 26:14). Apariciones notables incluyen el acto de celo de Finees (Nm 25:7), la ausencia de armas en la época de Débora (Jue 5:8) y la inversión escatológica de Joel (Jl 4:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136060, 'spa', 'Engaño', 'Engaño o traición como cualidad del habla, la acción o el carácter. Job protesta que sus labios no hablarán רְמִיָּה (Job 27:4; 13:7), emparejándolo con עַוְלָה. El Salmo 52:2 llama al impío artífice de traición, y el Sal 101:7 excluye de la corte a quien practica el engaño. El Salmo 32:2 celebra a quien no tiene רְמִיָּה en su espíritu.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136062, 'spa', 'Engañoso, traicionero', 'Engañoso o traicionero como cualidad atributiva que modifica otro sustantivo para crear una imagen compuesta. La expresión distintiva קֶשֶׁת רְמִיָּה, «arco traicionero» (Sal 78:57; Os 7:16), retrata a Israel como un arma que se quiebra o se desvía cuando su dueño más la necesita, prometiendo fiabilidad pero entregando traición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136063, 'spa', 'negligencia, desidia', 'Flojedad, negligencia y desidia culpable en la ejecución del trabajo o la responsabilidad. En Proverbios aparece como rasgo definitorio del perezoso: la ''mano negligente'' (כַּף רְמִיָּה, Prov 10:4) contrapuesta a las manos diligentes, y el alma indolente que se hunde en sueño profundo (19:15). Jeremías 48:10 eleva drásticamente las consecuencias: hacer la obra de Dios con רְמִיָּה merece maldición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136065, 'spa', 'El nombre propio Remalías (רְמַלְיָהוּ), conocido exclusivamente como el padre d', 'El nombre propio Remalías (רְמַלְיָהוּ), conocido exclusivamente como el padre de Pécaj, quien usurpó el trono israelita. El patronímico ''hijo de Remalías'' aparece en registros históricos (2 Re 15:25, 27, 30, 32, 37; 16:1, 5; 2 Cr 28:6) y, de manera llamativa, en la retórica profética de Isaías (Is 7:1, 4, 5, 9; 8:6), donde el profeta omite el nombre de Pécaj para expresar desprecio hacia la conspiración siro-efraimita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136067, 'spa', 'Levantarse, ser exaltado', 'Levantarse o ser exaltado, describiendo movimiento ascendente o elevación de estatus. Los querubines en la visión de Ezequiel ''se elevaron'' de la tierra (10:15, 17, 19), mientras que Sal 118:16 celebra la diestra del Señor como ''exaltada.'' En Isa 33:10, Dios mismo declara ''seré exaltado.'' La semántica consistente de movimiento hacia arriba une todas las ocurrencias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136070, 'spa', 'Apartarse, retirarse', 'Retirarse o apartarse de una situación peligrosa, como imperativo Nifal en Núm 16:45, donde Dios ordena a Moisés y Aarón separarse de la congregación rebelde de Coré antes de que caiga la ira divina. El español ''Apartaos'' reinterpreta el movimiento ascendente de la raíz como partida urgente. Esta única ocurrencia representa una extensión contextual del significado básico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136074, 'spa', 'Pisotear, hollar — sentido activo principal', 'Pisotear, hollar — sentido activo principal: pisar con fuerza, aplastar bajo los pies o hollar con intención destructiva. Abarca el pisoteo literal por personas, caballos o ejércitos (2 R 7:17, 20; 9:33) y se extiende a la opresión figurada. El imperativo Qal aparece en Isaías 41:25 para el alfarero que pisa la arcilla, y Miqueas 5:7 describe al remanente de Jacob pisoteando a sus enemigos como león entre ovejas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136091, 'spa', 'Ser pisoteado — sentido pasivo (Nifal)', 'Ser pisoteado — sentido pasivo (Nifal): ser hollado, pisoteado. Atestiguado solo en Isaías 28:3, donde la corona soberbia de los ebrios de Efraín ''será pisoteada''. Esta única ocurrencia constituye una forma verbal distinta que convierte al sujeto de agente en víctima de la misma acción violenta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136092, 'spa', 'Arrastrarse, pulular, moverse — desplazarse por el suelo reptando, arrastrándose', 'Arrastrarse, pulular, moverse — desplazarse por el suelo reptando, arrastrándose o pululando, dicho de animales pequeños como reptiles, insectos y otras criaturas a ras de suelo. Central en el relato sacerdotal de la creación (Gn 1:21, 26, 28, 30) y en la narrativa del Diluvio (Gn 7:8, 14; 8:17, 19), donde clasifica un modo distinto de locomoción animal. También aparece en la legislación alimentaria (Lv 11:44, 46; 20:25) y en Ezequiel 38:20 para una conmoción cósmica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136102, 'spa', 'Reptil, animal rastrero — sustantivo colectivo para las criaturas pequeñas que s', 'Reptil, animal rastrero — sustantivo colectivo para las criaturas pequeñas que se desplazan por el suelo (reptiles, insectos y otros rastreros), formando una categoría diferenciada en la taxonomía animal israelita. Aparece junto al ganado, las fieras y las aves en el relato de la creación (Gn 1:24-26; 6:7, 20; 7:14, 23; 8:17, 19). Se extiende a las criaturas marinas que se deslizan por las profundidades (Sal 104:25) y se usa figuradamente para la humanidad vulnerable y sin líder (Hab 1:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136113, 'spa', 'Ramot (topónimo) — nombre propio que designa ciudades elevadas, sobre todo Ramot', 'Ramot (topónimo) — nombre propio que designa ciudades elevadas, sobre todo Ramot de Galaad, ciudad de refugio en Gad (Dt 4:43; Jos 20:8) y enclave militar estratégico en las guerras entre Israel y Aram (1 R 22:3-6; 2 R 8:28; 9:1). Una segunda Ramot en Isacar es ciudad levítica (1 Cr 6:58). El nombre significa ''alturas'' y las traducciones multilingües lo transliteran uniformemente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136123, 'spa', 'Grito de gozo, canto alegre o exclamacion jubilosa, especialmente en la adoracio', 'Grito de gozo, canto alegre o exclamacion jubilosa, especialmente en la adoracion y celebracion de los actos salvificos de Dios. Las traducciones convergen en alabanza exuberante. Se empareja con accion de gracias (תּוֹדָה) en Sal 107:22 y con salvacion (יְשׁוּעָה) en Sal 118:15. Isaias lo despliega para la celebracion cosmica cuando Israel es redimido (Isa 35:10; 44:23; 49:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136124, 'spa', 'Clamor intenso de suplica, lamento o ruego urgente dirigido a Dios', 'Clamor intenso de suplica, lamento o ruego urgente dirigido a Dios. Se empareja constantemente con תְּפִלָּה (oracion) como par liturgico formal en la dedicacion del templo de Salomon (1 Re 8:28; 2 Cr 6:19) y en los salmos de peticion (Sal 17:1; 61:1; 88:2; 119:169; 142:6). Jeremias 7:16 y 14:12 muestran a Dios rechazando este clamor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136139, 'spa', 'Qal básico (16 apariciones)', 'Qal básico (16 apariciones): el grito espontáneo y vibrante de gozo o exultación, el evento vocal fundacional. El clamor del pueblo ante el sacrificio de Aarón (Lv 9:24), las estrellas de la mañana cantando en la creación (Job 38:7) y la Sion estéril a quien se ordena «¡Canta!» (Is 54:1) llevan esta fuerza Qal sin adorno.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136141, 'spa', 'Piel intensivo (27 apariciones)', 'Piel intensivo (27 apariciones): canto sostenido y exuberante, grito jubiloso. Intensifica el clamor básico en jubilación prolongada y deliberada: «¡Cantad con gozo, justos!» (Sal 33:1), «Mis labios gritarán de gozo cuando cante alabanzas a ti» (Sal 71:23), y los árboles del bosque «cantan de gozo» ante el SEÑOR (1 Cr 16:33).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136143, 'spa', 'Sentido Qal de clamar o vocear en voz alta (3 apariciones), donde la vocalizació', 'Sentido Qal de clamar o vocear en voz alta (3 apariciones), donde la vocalización es urgente o pública más que puramente gozosa. La Sabiduría «clama» en la calle (Pr 1:20), «llama» a la entrada de la ciudad (Pr 8:3), y Lm 2:19 ordena «clama en la noche». El paso del gozo a la urgencia se confirma por el uso de clamar en lugar del habitual cantar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136149, 'spa', 'Hifil causativo (5 apariciones)', 'Hifil causativo (5 apariciones): hacer cantar de gozo, provocar alabanza. Dios es el agente que suscita la alabanza de la creación y de su pueblo. Dt 32:43 convoca a las naciones a «regocijarse con su pueblo». Job 29:13 recuerda cómo la generosidad de Job «hacía cantar de gozo el corazón de la viuda». Sal 65:8 describe a Dios haciendo cantar de gozo las salidas de la mañana y la tarde.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136152, 'spa', 'Pual pasivo (1 aparición, Is 16', 'Pual pasivo (1 aparición, Is 16:10): indica que un grito de gozo «es cantado» o «es levantado». La voz pasiva señala la ausencia del canto habitual de vendimia: «ningún pisador pisa con gritos; el grito no es grito». Se describe el silencio estremecedor del juicio mediante lo que normalmente se oye pero ahora no se oye.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136155, 'spa', 'Hitpael reflexivo-intensivo (1 aparición, Sal 78', 'Hitpael reflexivo-intensivo (1 aparición, Sal 78:65): el SEÑOR que despierta «como quien grita», el tallo reflexivo añadiendo auto-involucramiento al clamor, como un guerrero que se anima a sí mismo con su propio grito de batalla. La morfología hitpael sugiere una agitación interna y autodirigida que irrumpe en fuerza vocal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136183, 'spa', 'Clamor gozoso', 'Denota un grito resonante de gozo o exultacion. Job 3:7 maldice la noche de su concepcion para que sea esteril: ''que no entre en ella grito de jubilo'' (רְנָנָה). Job 20:5 describe ''el triunfo del impio'' (רִנַּת רְשָׁעִים) como algo momentaneo. Salmo 63:5 habla de alabar a Dios ''con labios de canticos jubilosos'' (שִׂפְתֵי רְנָנוֹת).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136187, 'spa', 'Brida o freno', 'Designa una brida o cabestro para controlar animales, con posible extension al sentido de quijada. Salmo 32:9 empareja ''freno y cabestro'' (מֶתֶג וָרֶסֶן) para sujetar caballos y mulos. Isaias 30:28 usa ''freno en las quijadas de los pueblos'' (רֶסֶן עַל־לְחָיֵי עַמִּים) como metafora del dominio de Dios sobre las naciones. Job 30:11 describe a quienes desechan toda sujecion.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136190, 'spa', 'El mal (הָרַע), el adjetivo sustantivado con el artículo definido que designa el', 'El mal (הָרַע), el adjetivo sustantivado con el artículo definido que designa el acto o persona moralmente perversa que amenaza la santidad comunitaria. En español ''el mal'' y en francés ''le mal'' capturan la fuerza sustantival. Casi todas las 14 ocurrencias se agrupan en las fórmulas de purga deuteronómica —''quitarás el mal de en medio de ti'' (Dt 17:12; 19:19; 21:21; 22:21–22)— funcionando como término técnico legal que marca ofensas capitales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136192, 'spa', 'moralmente malo, malvado', 'Moralmente malo o perverso: describe personas, conductas, corazones o actos como éticamente corruptos. Es el sentido dominante (129 casos), que ancla los grandes juicios morales de la Escritura. Gn 6:5 declara que todo pensamiento del corazón era ''solo mal continuamente'', y los historiadores deuteronomistas condenan repetidamente a los reyes que ''hicieron lo malo ante los ojos de Jehová''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136193, 'spa', 'mal, daño, calamidad', 'El mal sustantivado como daño, calamidad o desastre: el uso nominal abstracto donde רָעָה denota desgracia, adversidad o consecuencia destructiva que recae sobre alguien. Deuteronomio advierte que la desobediencia provoca a Dios ''para mal'' contra el pueblo (Dt 4:25; 9:18), y los oráculos proféticos de juicio anuncian רָעָה como castigo inminente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136196, 'spa', 'malo, de mala calidad', 'Malo en calidad, inútil o inferior: describe cosas deficientes o pobres sin reproche moral. Labán no puede hablar a Jacob ''ni bien ni mal'' (Gn 24:50), las vacas escuálidas de Faraón están simplemente en mal estado (Gn 41:21), y Jacob lamenta sus años como ''pocos y malos'' (Gn 47:9). El contexto señala evaluación cualitativa, no ética.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136208, 'spa', 'feo, de mal aspecto', 'Feo, de mal aspecto o apariencia: concentrado en el sueño de Faraón con las siete vacas ''feas y flacas'' (Gn 41:3, 4, 19, 20, 27). Árabe قَبِيح y alemán hässlich emplean vocabulario estético dedicado, demostrando que los traductores reconocen mundialmente este sentido como un juicio visual, no moral ni cualitativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136212, 'spa', 'grave, feroz, peligroso', 'Grave, feroz o peligroso: describe fieras, plagas terribles o castigos severos. Una ''bestia רָעָה'' ha devorado a José (Gn 37:20, 33); Deuteronomio advierte sobre ''enfermedades רָעוֹת'' y ''señales grandes y terribles'' (Dt 6:22; 2 Cr 21:19). Árabe شَدِيد y coreano 심한 marcan una escala de peligro más que de falta moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136214, 'spa', 'triste, afligido', 'Triste, abatido o disgustado en el semblante o el ánimo. Nehemías se presenta ante el rey con un ''rostro רַע'' — no malvado sino apenado (Neh 2:1-2). El rey pregunta de inmediato: ''¿por qué está triste tu rostro?'', reconociendo tristeza, no maldad. Árabe حَزِين y español triste confirman el registro emocional de esta acepción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136241, 'spa', 'maldad moral', 'Maldad o perversidad moral como concepto abstracto: el sentido dominante (83 apariciones), opuesto sustantivo de ''bien'' en el marco moral bíblico. Es el רַע del árbol del conocimiento del bien y del mal (Gn 2:9, 17; 3:5, 22), la fórmula ''lo malo ante los ojos de Jehová'' y la denuncia profética de quienes ''maquinan mal'' (Mi 2:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136242, 'spa', 'malo, de mala calidad', 'Malo, de mala calidad o desagradable: 9 apariciones donde רַע funciona como adjetivo cualitativo sin juicio moral primario. Ecl 9:3 (''esto es un mal en todo lo que se hace bajo el sol'') describe una condición indeseable más que maldad. En 1 R 22:8, 18, Micaías ''nunca profetiza bien sino mal'', es decir, noticias desfavorables.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136247, 'spa', 'calamidad, desgracia', 'Calamidad, desastre o infortunio: 7 apariciones donde רַע nombra sufrimiento o circunstancias adversas, no carácter moral. Los israelitas ven que están ''en mal'' (Éx 5:19), el salmista confía en Dios en ''el día malo'' (Sal 49:5), e Is 45:7 es la cúspide teológica: Dios declara ''hago la paz y creo la adversidad''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136252, 'spa', 'malvado (de personas)', 'Malo o perverso dicho de personas: 3 apariciones donde רַע caracteriza a una persona como moralmente malvada o funciona sustantivamente como ''el malvado / el impío''. En Sal 140:11 ''no permanezca el hombre malo en la tierra''; en Sal 119:101 ''de todo mal camino contuve mis pies''; en Pr 29:6 ''en la transgresión del hombre malo hay lazo''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136254, 'spa', 'daño, perjuicio', 'Daño o perjuicio dirigido contra personas: 3 apariciones donde רַע denota daño concreto o intención de hacer mal, no maldad abstracta. En Jer 7:6 se advierte no causar ''mal'' (לְרַע) al extranjero, huérfano y viuda; en Jer 25:7 provocaron a Dios ''para vuestro propio mal''; en Ecl 8:9 alguien ejerce autoridad ''para su mal''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136266, 'spa', 'maldad moral', 'El sentido dominante: maldad, perversidad o pecaminosidad abstracta como cualidad o condición. Abarca cerca del 77% de las apariciones, en construcciones como ''la maldad del corazón'' (Gn 6:5) y ''devolver mal por bien'' (Gn 44:4). Todas las lenguas principales de destino convergen en un término único de maldad moral: inglés evil, español mal, francés mal, alemán Böses.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136272, 'spa', 'daño, perjuicio', 'Daño o perjuicio dirigido a una persona específica, centrado en el efecto dañino más que en el carácter moral o el juicio cósmico. Gn 31:52 (''este majano es testigo... de que no pasaré... para hacerte mal'') y Sal 35:4 (''sean confundidos los que traman mi mal'') ilustran la dimensión interpersonal e intencional de esta acepción.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136275, 'spa', 'maldades, actos malvados', 'Actos malvados concretos en plural: acciones específicas contables más que la cualidad abstracta. Dt 31:17 (''muchos males y angustias les sobrevendrán'') y Sal 40:12 (''me han rodeado males innumerables'') ejemplifican este uso pluralizado y enumerativo. El español emplea ''maldades'' y ''males'', y el francés ''maux'', confirmando el paso de lo abstracto a lo concreto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136276, 'spa', 'calamidad, desastre', 'Catástrofe externa, desastre o ruina, típicamente enviada por Dios o experimentada como juicio. Se distingue del sentido 1 por la ausencia de agencia moral en quien sufre: la רָעָה viene sobre ellos. Pasajes clave: 1 R 9:9 (''trajo sobre ellos toda esta calamidad'') y Jue 20:34, 41, donde el desastre militar abruma a Benjamín.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136284, 'spa', 'aflicción, angustia', 'Aflicción, tribulación o angustia subjetiva experimentada por una persona, enfatizando el sufrimiento vivido más que la falta moral o la catástrofe externa. Nm 11:15 (''no me hagas ver mi desventura'') y Neh 1:3 (''los sobrevivientes están en gran aflicción'') se centran en la dimensión experiencial. Alemán Trübsal (tribulación) aparece en este grupo, distinto de Böses.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136353, 'spa', 'sonido fuerte y ruidoso', 'El término designa sonido fuerte y contundente en tres pasajes disputados. Éxodo 32:17 describe ''el sonido del pueblo en su griterío'' (o ''mientras gritan'') cuando adoraron el becerro de oro—el ruido de celebración que Moisés escuchó al descender del monte. Job 36:33 es textualmente difícil; algunos leen ''su trueno'' (ra''mo) mientras el TM tiene ''su rugido'' (re''o), refiriéndose a la tormenta que anuncia a Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136354, 'spa', 'prójimo, semejante', 'Prójimo o miembro de la comunidad: el sentido legal-ético dominante con 120 apariciones. Es el רֵעַ de los Diez Mandamientos (Éx 20:17; Dt 5:20), del ''amarás a tu prójimo'' del Código de Santidad (Lv 19:18) y de las denuncias proféticas de injusticia social. Árabe جَار y coreano 이웃 marcan consistentemente proximidad y obligación, no afecto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136361, 'spa', 'amigo', 'Amigo, persona unida por afecto personal y lealtad: 48 apariciones concentradas en textos narrativos y sapienciales. El רֵעַ de Judá, Hirá el adulamita (Gn 38:12, 20), Moisés como רֵעַ de Dios (Éx 33:11), y las reflexiones de Proverbios sobre la amistad fiel (Pr 17:17; 27:6, 9-10). Árabe صَدِيق y coreano 친구 seleccionan vocabulario de amistad verdadera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136364, 'spa', 'compañero, asociado', 'Compañero, asociado o par definido por circunstancia o actividad compartida: 21 apariciones. Cubre compañeros de viaje (Gn 43:33), soldados camaradas (Jue 7:13-14), colaboradores e interlocutores. La distinción clave frente al sentido 2 es que el vínculo es circunstancial, no afectivo: están juntos por lo que hacen, no porque se hayan elegido mutuamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136421, 'spa', 'amante, pretendiente', 'Amante o pretendiente en un contexto de connotación sexual: la única aparición en Jer 3:1, donde Israel es comparado con una mujer que ''va tras muchos amantes'' (רֵעִים). Jeremías emplea la calidez relacional de la palabra para agudizar la acusación de adulterio espiritual. Inglés lovers y español amantes traducen explícitamente la carga erótica de la metáfora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (136422, 'spa', 'contraparte, par', 'Contraparte o mitad correspondiente: única aparición en Gn 15:10, en la ceremonia del pacto, donde cada pieza del animal se coloca ''frente a su compañera'' (רֵעֵהוּ). Aquí רֵעַ significa la parte correspondiente de un todo dividido. Alemán dem anderen y español compañero de él captan este sentido de emparejamiento en el pacto de Dios con Abraham.');